"use client";

import { useActionState } from "react";
import type { FormState } from "./actions";

const input = "mt-1 w-full rounded border border-black/20 bg-transparent px-3 py-2 dark:border-white/25";

export function AuthForm({
  action,
  submitLabel,
  callbackUrl,
  withName,
}: {
  action: (s: FormState, f: FormData) => Promise<FormState>;
  submitLabel: string;
  callbackUrl?: string;
  withName?: boolean;
}) {
  const [state, formAction, pending] = useActionState(action, undefined);
  return (
    <form action={formAction} className="space-y-4">
      {callbackUrl && <input type="hidden" name="callbackUrl" value={callbackUrl} />}
      {withName && (
        <label className="block text-sm">
          Name
          <input name="name" required autoComplete="name" className={input} />
        </label>
      )}
      <label className="block text-sm">
        Email
        <input name="email" type="email" required autoComplete="email" className={input} />
      </label>
      <label className="block text-sm">
        Password
        <input
          name="password"
          type="password"
          required
          minLength={withName ? 8 : undefined}
          autoComplete={withName ? "new-password" : "current-password"}
          className={input}
        />
      </label>
      {state?.error && (
        <p role="alert" className="text-sm text-red-600">
          {state.error}
        </p>
      )}
      <button
        disabled={pending}
        className="w-full rounded bg-foreground px-4 py-2 text-background disabled:opacity-50"
      >
        {submitLabel}
      </button>
    </form>
  );
}
